from itertools import combinations

def combinations_3(k):
    if k < 3:
        return 0
    return k * (k - 1) * (k - 2) // 6

def M(n):
    min_val = float('inf')

    # Iterate over possible counts for red stars (r)
    # r ranges from 0 up to n/2 to avoid checking symmetric pairs
    for r in range(n // 2 + 1):
        b = n - r

        # Calculate the total number of monochromatic triangles
        count = combinations_3(r) + combinations_3(b)

        if count < min_val:
            min_val = count
    return min_val

for n in [5, 6, 7]:
    result = M(n)
    print(f"M({n}) = {result}")
